"use client";
import { ArtemisScope } from "./artemis-scope";
import View1 from "./components/credit-usage/variants/02-breakdown";
const variants={"breakdown":View1};
export interface ArtemisCreditUsageProps { className?: string; variant?: "breakdown"; }
export function ArtemisCreditUsage({className,variant="breakdown"}:ArtemisCreditUsageProps) {const View=variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import { useId as useArtemisInstanceId } from "react";
import { ArrowDown, ChevronDown, Download, Search, SlidersHorizontal, X } from "lucide-react";
import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { useEffect, useRef, useState } from "react";
import { ArtemisButton } from "../../../foundations/button";
import { artemisButtonClasses } from "../../../foundations/button-classes";
import { ArtemisDigitSwap } from "../../../foundations/digit-swap";
import { ArtemisSegmentedTabs } from "../../../foundations/segmented-tabs";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PANEL, ARTEMIS_SPRING_SWAP } from "../../../lib/ease";
import { BAR_CEILING, CATEGORIES, type CategoryId, fmt, PERIODS, type PeriodId, SORT_COLUMNS, type SortKey, scaleRow, STAT_LABELS, VIEWS, type ViewId, } from "./02-breakdown/data";
import { NumberTicker } from "./02-breakdown/number-ticker";
import { StatefulButton, type ButtonState } from "./02-breakdown/stateful-button";
const SEGMENT = "art:items-center art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:inline-block art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:relative art:h-full art:min-w-0 art:after:absolute art:after:-inset-y-3 art:after:inset-x-0 art:after:content-[''] art:rounded-full";
const LEGEND = "art:justify-center art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-auto art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:flex art:min-h-8 art:items-center art:gap-2 art:px-1 art:transition-opacity art:duration-200 art:rounded-full";
const SORT_BASE = "art:justify-center art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-auto art:p-0 art:font-normal";
const REVEAL_HIDDEN = { opacity: 0, filter: "blur(6px)", y: 14 };
const REVEAL_SHOWN = { opacity: 1, filter: "blur(0px)", y: 0 };
const reveal = (delay: number): Transition => ({ duration: 0.55, ease: ARTEMIS_EASE_OUT, delay });
const GROW = { duration: 0.7, ease: ARTEMIS_EASE_OUT } as const;
const DIM = { duration: 0.2, ease: "easeOut" } as const;
const TIP_EXIT = { duration: 0.14, ease: [0.4, 0, 1, 1] } as const;
const SWAP = { duration: 0.16, ease: ARTEMIS_EASE_OUT } as const;
const INSTANT = { duration: 0 } as const;
const LAYOUT = { type: "spring", stiffness: 521.1, damping: 47.75, mass: 1 } as const;
const ROW_ENTER: Transition = {
    layout: LAYOUT,
    y: LAYOUT,
    opacity: { duration: 0.25, ease: "easeOut" },
    filter: { duration: 0.3, ease: "easeOut" },
};
const ROW_EXIT = { opacity: 0, transition: TIP_EXIT };
const VISIBLE_ROWS = 5;
const pct = (v: number) => `${Number(v.toFixed(4))}%`;
export default function CreditUsageBreakdown() {
const artemisInstanceId = useArtemisInstanceId();

    const reduce = useReducedMotion() ?? false;
    const [periodId, setPeriodId] = useState<PeriodId>("30d");
    const [view, setView] = useState<ViewId>("workflows");
    const [hovered, setHovered] = useState<CategoryId | null>(null);
    const [selected, setSelected] = useState<CategoryId | null>(null);
    const [filterOpen, setFilterOpen] = useState(false);
    const [query, setQuery] = useState("");
    const [focused, setFocused] = useState(false);
    const [sortKey, setSortKey] = useState<SortKey>("credits");
    const [expanded, setExpanded] = useState(false);
    const [exportState, setExportState] = useState<ButtonState>("idle");
    const timers = useRef<number[]>([]);
    useEffect(() => () => timers.current.forEach((t) => window.clearTimeout(t)), []);
    const period = PERIODS.find((p) => p.id === periodId) ?? PERIODS[1];
    const active = hovered ?? selected;
    const shares = CATEGORIES.map((c) => Number(((period.categories[c.id] / period.limit) * 100).toFixed(4)));
    const free = Number((((period.limit - period.used) / period.limit) * 100).toFixed(4));
    const centreOf = (id: CategoryId) => {
        const i = CATEGORIES.findIndex((c) => c.id === id);
        return shares.slice(0, i).reduce((sum, s) => sum + s, 0) + shares[i] / 2;
    };
    const viewData = VIEWS[view];
    const q = query.trim().toLowerCase();
    const rows = viewData.rows
        .map((r) => scaleRow(r, period.factor))
        .filter((r) => selected === null || r.category === selected)
        .filter((r) => {
        if (!q)
            return true;
        const label = CATEGORIES.find((c) => c.id === r.category)?.label ?? "";
        return [r.name, r.detail, label].some((s) => s.toLowerCase().includes(q));
    })
        .sort((a, b) => b[sortKey] - a[sortKey]);
    const shown = expanded ? rows : rows.slice(0, VISIBLE_ROWS);
    const toggle = (id: CategoryId) => setSelected((prev) => (prev === id ? null : id));
    const handlers = (id: CategoryId) => ({
        onMouseEnter: () => setHovered(id),
        onMouseLeave: () => setHovered((prev) => (prev === id ? null : prev)),
        onFocus: () => setHovered(id),
        onBlur: () => setHovered((prev) => (prev === id ? null : prev)),
        onClick: () => toggle(id),
    });
    const runExport = () => {
        if (exportState !== "idle")
            return;
        setExportState("loading");
        timers.current.push(window.setTimeout(() => setExportState("success"), 900), window.setTimeout(() => setExportState("idle"), 2300));
    };
    const hoveredCategory = CATEGORIES.find((c) => c.id === hovered);
    const selectedCategory = CATEGORIES.find((c) => c.id === selected);
    return (<>
      <section aria-labelledby={`${artemisInstanceId}-credit-usage-title`} className="art:w-full art:font-sans art:text-foreground">
        <div className="art:mx-auto art:w-full art:max-w-5xl">
          <motion.div className="art:flex art:flex-col art:gap-5 art:@min-[640px]/artemis:flex-row art:@min-[640px]/artemis:items-end art:@min-[640px]/artemis:justify-between" initial={reduce ? false : REVEAL_HIDDEN} animate={REVEAL_SHOWN} transition={reveal(0)}>
            <div>
              <h2 id={`${artemisInstanceId}-credit-usage-title`} className="art:font-medium art:text-4xl art:tracking-tight">
                {"Credits this cycle"}
              </h2>
              <p className="art:mt-2 art:text-muted-foreground">{"See which workflows and teammates spent your credits."}</p>
            </div>
            <div>
              <ArtemisSegmentedTabs ariaLabel="Reporting period" items={PERIODS.map((p) => ({ value: p.id, label: p.label }))} value={periodId} onValueChange={(v) => setPeriodId(v as PeriodId)}/>
            </div>
          </motion.div>
          <motion.div className="art:mt-8" initial={reduce ? false : REVEAL_HIDDEN} animate={REVEAL_SHOWN} transition={reveal(0.08)}>
            <div className="art:rounded-3xl art:border art:border-border art:bg-background art:p-5 art:@min-[640px]/artemis:p-7">
              <div className="art:flex art:flex-wrap art:items-start art:justify-between art:gap-4">
                <div>
                  <p className="art:font-medium">{"Scale plan"}</p>
                  <p className="art:mt-1 art:flex art:flex-wrap art:items-center art:gap-1 art:text-muted-foreground art:text-sm">
                    <NumberTicker text={fmt(period.used)}/>
                    {"of "}
                    {fmt(period.limit)}
                    {" "}
                    {"credits used"}
                  </p>
                </div>
                <ArtemisButton variant="tertiary" size="sm">
                  {"Change plan"}
                </ArtemisButton>
              </div>
              <figure aria-label="Credits used by category" className="art:m-0 art:w-full">
                <div className="art:relative art:mt-14">
                  <AnimatePresence>
                    {hoveredCategory && (<motion.div key="tip" aria-hidden="true" className="art:pointer-events-none art:absolute art:bottom-full art:z-10 art:mb-3 art:-translate-x-1/2 art:whitespace-nowrap art:rounded-2xl art:border art:border-border art:bg-background art:px-3.5 art:py-2.5" initial={{ opacity: 0, left: pct(centreOf(hoveredCategory.id)), y: 6, scale: 0.96 }} animate={{ opacity: 1, left: pct(centreOf(hoveredCategory.id)), y: 0, scale: 1 }} exit={{ opacity: 0, y: 4, scale: 0.97, transition: reduce ? INSTANT : TIP_EXIT }} transition={reduce ? INSTANT : ARTEMIS_SPRING_SWAP}>
                        <AnimatePresence mode="popLayout" initial={false}>
                          <motion.div key={hoveredCategory.id} initial={{ opacity: 0, y: 4 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -4 }} transition={reduce ? INSTANT : SWAP}>
                            <p className="art:font-medium art:text-sm">{hoveredCategory.label}</p>
                            <p className="art:mt-0.5 art:text-muted-foreground art:text-xs art:tabular-nums">
                              {fmt(period.categories[hoveredCategory.id])} credits · {((period.categories[hoveredCategory.id] / period.used) * 100).toFixed(1)}% of use
                            </p>
                          </motion.div>
                        </AnimatePresence>
                      </motion.div>)}
                  </AnimatePresence>
                  <div className="art:flex art:h-2.5 art:w-full art:gap-1">
                    {CATEGORIES.map((c, i) => (<motion.button key={c.id} type="button" className={SEGMENT} aria-label={`${c.label}: ${fmt(period.categories[c.id])} credits`} aria-pressed={selected === c.id} style={{ flexBasis: "0px", originX: 0 }} initial={reduce ? false : { scaleX: 0, opacity: 1, flexGrow: shares[i] }} animate={{ scaleX: 1, flexGrow: shares[i], opacity: active !== null && active !== c.id ? 0.35 : 1 }} transition={{
                scaleX: reduce ? INSTANT : { ...GROW, delay: 0.35 + i * 0.08 },
                flexGrow: reduce ? INSTANT : LAYOUT,
                opacity: reduce ? INSTANT : DIM,
            }} {...handlers(c.id)}>
                        <span className={`art:absolute art:inset-0 art:rounded-full ${c.bar}`}/>
                      </motion.button>))}
                    <motion.span aria-hidden="true" className="art:h-full art:rounded-full art:bg-muted" style={{ flexBasis: "0px" }} initial={false} animate={{ flexGrow: free }} transition={reduce ? INSTANT : LAYOUT}/>
                  </div>
                </div>
                <div className="art:mt-4 art:flex art:flex-wrap art:items-center art:gap-x-5 art:gap-y-2 art:text-sm">
                  {CATEGORIES.map((c) => (<button key={c.id} type="button" className={`${LEGEND}${active !== null && active !== c.id ? " art:opacity-40" : ""}`} aria-pressed={selected === c.id} {...handlers(c.id)}>
                      <span className={`art:size-2 art:rounded-full ${c.bar}`}/>
                      <span className="art:text-muted-foreground">{c.label}</span>
                      <ArtemisDigitSwap value={`${(period.categories[c.id] / 1000).toFixed(1)}k`} className="art:font-mono art:text-foreground art:text-xs art:tabular-nums"/>
                    </button>))}
                  <span className="art:ml-auto art:text-muted-foreground art:text-xs">{period.renews}</span>
                </div>
              </figure>
              <dl className="art:mt-6 art:grid art:grid-cols-2 art:gap-y-6 art:border-border art:border-t art:pt-6 art:@min-[768px]/artemis:grid-cols-4">
                {STAT_LABELS.map((label, i) => (<div key={label} className={`art:flex art:flex-col-reverse art:gap-1${i > 0 ? " art:@min-[768px]/artemis:border-border art:@min-[768px]/artemis:border-l art:@min-[768px]/artemis:pl-6" : ""}${i % 2 === 1 ? " art:border-border art:border-l art:pl-6" : ""}`}>
                    <dt className="art:text-muted-foreground art:text-sm">{label}</dt>
                    <dd className="art:font-medium art:text-4xl art:tracking-tight">
                      <NumberTicker text={fmt(period.stats[i])} entrance/>
                    </dd>
                  </div>))}
              </dl>
            </div>
          </motion.div>
          <motion.div className="art:mt-10" initial={reduce ? false : REVEAL_HIDDEN} animate={REVEAL_SHOWN} transition={reveal(0.16)}>
            <div className="art:flex art:flex-col art:gap-3 art:@min-[768px]/artemis:flex-row art:@min-[768px]/artemis:items-center art:@min-[768px]/artemis:justify-between">
              <div>
                <ArtemisSegmentedTabs ariaLabel="Breakdown" items={(Object.keys(VIEWS) as ViewId[]).map((v) => ({ value: v, label: VIEWS[v].tab }))} value={view} onValueChange={(v) => setView(v as ViewId)}/>
              </div>
              <div className="art:flex art:flex-wrap art:items-center art:gap-2">
                <div className="art:flex art:flex-col art:gap-1.5 art:w-full art:basis-full art:@min-[768px]/artemis:w-64 art:@min-[768px]/artemis:basis-auto">
                  <div data-state={focused ? "focused" : "idle"} className={`art:relative art:h-10 art:overflow-hidden art:rounded-full art:border art:bg-background art:transition-colors art:duration-200 ${focused ? "art:border-foreground/60" : "art:border-border"}`}>
                    <span className="art:pointer-events-none art:absolute art:left-3 art:top-1/2 art:flex art:-translate-y-1/2 art:items-center art:text-muted-foreground art:[&_svg]:h-4 art:[&_svg]:w-4">
                      <Search className="art:size-4" aria-hidden="true"/>
                    </span>
                    <input placeholder={viewData.placeholder} aria-label="Search breakdown" className="art:peer art:h-full art:w-full art:bg-transparent art:text-sm art:leading-6 art:text-foreground art:caret-foreground art:outline-none art:placeholder:text-muted-foreground/60 art:pl-10 art:pr-3.5" value={query} onChange={(e) => setQuery(e.target.value)} onFocus={() => setFocused(true)} onBlur={() => setFocused(false)}/>
                  </div>
                  <div className="art:contents"/>
                </div>
                <StatefulButton className={artemisButtonClasses({ variant: "tertiary", size: "md", className: "art:h-10" })} tabIndex={0} state={exportState} loadingText="Exporting" successText="Exported" onClick={runExport}>
                  <Download className="art:size-4" aria-hidden="true"/>
                  {"Export"}
                </StatefulButton>
                <ArtemisButton variant="tertiary" size="md" className="art:h-10" aria-expanded={filterOpen} onClick={() => setFilterOpen((o) => !o)}>
                  <SlidersHorizontal className="art:size-4" aria-hidden="true"/>
                  {"Filter"}
                  {selected ? <span className="art:grid art:size-5 art:place-items-center art:rounded-full art:bg-muted art:font-medium art:text-xs">{"1"}</span> : null}
                </ArtemisButton>
              </div>
            </div>
            <AnimatePresence initial={false}>
              {filterOpen && (<motion.div key="filters" className="art:overflow-hidden" initial={{ height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={reduce ? INSTANT : ARTEMIS_SPRING_PANEL}>
                  <div className="art:flex art:flex-wrap art:items-center art:gap-2 art:pt-4">
                    <span className="art:mr-1 art:text-muted-foreground art:text-sm">{"Category"}</span>
                    {CATEGORIES.map((c) => (<ArtemisButton key={c.id} variant={selected === c.id ? "primary" : "tertiary"} size="sm" aria-pressed={selected === c.id} onClick={() => toggle(c.id)}>
                        {c.label}
                      </ArtemisButton>))}
                  </div>
                </motion.div>)}
            </AnimatePresence>
            <AnimatePresence initial={false}>
              {selectedCategory && (<motion.div key="active-filter" className="art:mt-4" initial={{ opacity: 0, y: -4 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -4 }} transition={reduce ? INSTANT : ARTEMIS_SPRING_PANEL}>
                  <ArtemisButton variant="tertiary" size="sm" aria-label={`Clear ${selectedCategory.label} filter`} onClick={() => setSelected(null)}>
                    {selectedCategory.label}
                    <X className="art:size-3.5" aria-hidden="true"/>
                  </ArtemisButton>
                </motion.div>)}
            </AnimatePresence>
            <div className="art:mt-5 art:overflow-x-auto art:rounded-3xl art:border art:border-border">
              <table className="art:w-full art:min-w-2xl art:text-left art:text-sm">
                <caption className="art:sr-only">
                  {"Credit use by "}
                  {viewData.column}
                </caption>
                <thead className="art:border-border art:border-b art:text-muted-foreground">
                  <tr>
                    <th scope="col" className="art:px-5 art:py-3.5 art:font-normal">
                      {viewData.column}
                    </th>
                    <th scope="col" className="art:px-5 art:py-3.5 art:font-normal">
                      {"Category"}
                    </th>
                    {SORT_COLUMNS.map((col) => {
            const on = sortKey === col.key;
            return (<th key={col.key} scope="col" aria-sort={on ? "descending" : "none"} className="art:px-5 art:py-2 art:text-right art:font-normal">
                          <button type="button" className={`${SORT_BASE} ${on ? "" : "art:text-inherit "}art:hover:bg-transparent art:inline-flex art:min-h-8 art:items-center art:gap-1 art:px-1 art:transition-colors art:hover:text-foreground ${on ? "art:text-foreground " : ""}art:rounded-full`} onClick={() => setSortKey(col.key)}>
                            {col.label}
                            <ArrowDown className={`art:size-3.5 art:transition-[opacity,transform] art:duration-200 ${on ? "art:opacity-100" : "art:-translate-y-0.5 art:opacity-0"}`} aria-hidden="true"/>
                          </button>
                        </th>);
        })}
                    <th scope="col" className="art:px-5 art:py-3.5 art:text-right art:font-normal">
                      {"Share"}
                    </th>
                  </tr>
                </thead>
                <tbody>
                  <AnimatePresence initial={false} mode="popLayout">
                    {shown.map((row) => {
            const category = CATEGORIES.find((c) => c.id === row.category) ?? CATEGORIES[0];
            const share = row.credits / period.used;
            return (<motion.tr key={`${view}-${row.id}`} layout={!reduce} className="art:border-border art:border-b art:last:border-b-0" initial={reduce ? false : { opacity: 0, filter: "blur(4px)", y: 10 }} animate={{ opacity: active !== null && active !== row.category ? 0.4 : 1, filter: "blur(0px)", y: 0 }} exit={reduce ? { opacity: 0, transition: INSTANT } : ROW_EXIT} transition={reduce ? INSTANT : ROW_ENTER}>
                          <th scope="row" className="art:px-5 art:py-4 art:font-normal">
                            <span className="art:flex art:items-center art:gap-3">
                              {row.avatar ? <img alt="" width={32} height={32} className="art:size-8 art:rounded-full art:object-cover" src={row.avatar}/> : null}
                              <span>
                                <span className="art:block art:font-medium">{row.name}</span>
                                <span className="art:block art:text-muted-foreground art:text-xs">{row.detail}</span>
                              </span>
                            </span>
                          </th>
                          <td className="art:px-5 art:py-4">
                            <span className={`art:inline-flex art:items-center art:rounded-full art:border art:px-2.5 art:py-1 art:font-medium art:text-xs ${category.badge}`}>{category.label}</span>
                          </td>
                          <td className="art:px-5 art:py-4 art:text-right art:font-mono art:tabular-nums">
                            <NumberTicker text={fmt(row.runs)}/>
                          </td>
                          <td className="art:px-5 art:py-4 art:text-right art:font-mono art:tabular-nums">
                            <NumberTicker text={fmt(row.hours)}/>
                          </td>
                          <td className="art:px-5 art:py-4 art:text-right art:font-mono art:tabular-nums">
                            <NumberTicker text={fmt(row.credits)}/>
                          </td>
                          <td className="art:px-5 art:py-4">
                            <span className="art:flex art:items-center art:justify-end art:gap-3">
                              <span className="art:hidden art:h-1 art:w-16 art:overflow-hidden art:rounded-full art:bg-muted art:@min-[640px]/artemis:block">
                                <motion.span className={`art:block art:h-full art:origin-left art:rounded-full ${category.bar}`} initial={false} animate={{ scaleX: share / BAR_CEILING }} transition={reduce ? INSTANT : LAYOUT}/>
                              </span>
                              <span className="art:w-12 art:text-right art:font-mono art:tabular-nums">
                                {(share * 100).toFixed(1)}
                                {"%"}
                              </span>
                            </span>
                          </td>
                        </motion.tr>);
        })}
                  </AnimatePresence>
                </tbody>
              </table>
              {rows.length === 0 ? <p className="art:px-5 art:py-10 art:text-center art:text-muted-foreground art:text-sm">{"Nothing matches that search."}</p> : null}
            </div>
            {rows.length > VISIBLE_ROWS ? (<div className="art:relative">
                {expanded ? null : (<div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-x-0 art:-top-24 art:h-24 art:bg-gradient-to-t art:from-background art:to-transparent"/>)}
                <div className="art:flex art:justify-center art:pt-4">
                  <ArtemisButton variant="ghost" size="sm" aria-expanded={expanded} onClick={() => setExpanded((e) => !e)}>
                    {expanded ? "Show less" : `Show all ${rows.length}`}
                    <ChevronDown className={`art:size-3.5 art:transition-transform art:duration-200${expanded ? " art:rotate-180" : ""}`} aria-hidden="true"/>
                  </ArtemisButton>
                </div>
              </div>) : null}
          </motion.div>
        </div>
      </section>
    </>);
}

import { artemisDemoAvatar } from "../../../../lib/demo-avatar";
// @zeus-internal
export type PeriodId = "7d" | "30d" | "quarter";
export type CategoryId = "drafting" | "analysis" | "translation" | "data-sync";
export type ViewId = "workflows" | "teammates";
export type SortKey = "runs" | "hours" | "credits";
export const PERIODS: readonly {
    id: PeriodId;
    label: string;
    factor: number;
    used: number;
    limit: number;
    renews: string;
    categories: Record<CategoryId, number>;
    stats: readonly [
        number,
        number,
        number,
        number
    ];
}[] = [
    {
        id: "7d",
        label: "7 days",
        factor: 0.24,
        used: 104200,
        limit: 125000,
        renews: "Renews Monday",
        categories: { drafting: 31400, analysis: 38900, translation: 19200, "data-sync": 14700 },
        stats: [1184, 11, 268, 87],
    },
    {
        id: "30d",
        label: "30 days",
        factor: 1,
        used: 427200,
        limit: 500000,
        renews: "Renews Nov 1",
        categories: { drafting: 128600, analysis: 154300, translation: 81900, "data-sync": 62400 },
        stats: [4912, 17, 1096, 87],
    },
    {
        id: "quarter",
        label: "Quarter",
        factor: 2.85,
        used: 1208600,
        limit: 1500000,
        renews: "Renews Jan 1",
        categories: { drafting: 371200, analysis: 412800, translation: 236500, "data-sync": 188100 },
        stats: [14260, 21, 3310, 85],
    },
];
export const STAT_LABELS = ["Tasks completed", "Active workflows", "Hours returned", "Credits per task"] as const;
