export function scaleRow(row: BreakdownRow, factor: number): BreakdownRow {
    if (factor === 1)
        return row;
    return {
        ...row,
        runs: Math.round(row.runs * factor),
        hours: Math.round(row.hours * factor),
        credits: Math.round(row.credits * factor),
    };
}
